export const confirmResetPassword = (
  confirmPasswordResetRequest: BodyType<ConfirmPasswordResetRequest>,
  options?: SecondParameter<typeof createInstance>,
  signal?: AbortSignal,
) => {
  return createInstance<ConfirmPasswordResetResponse>(
    {
      url: `/auth/reset-password/confirm`,
      method: "POST",
      headers: { "Content-Type": "application/json" },
      data: confirmPasswordResetRequest,
      signal,
    },
    options,
  );
};

export const getConfirmResetPasswordMutationOptions = <
  TError = ErrorType<HTTPValidationError>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof confirmResetPassword>>,
    TError,
    { data: BodyType<ConfirmPasswordResetRequest> },
    TContext
  >;
  request?: SecondParameter<typeof createInstance>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof confirmResetPassword>>,
  TError,
  { data: BodyType<ConfirmPasswordResetRequest> },
  TContext
> => {
  const mutationKey = ["confirmResetPassword"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof confirmResetPassword>>,
    { data: BodyType<ConfirmPasswordResetRequest> }
  > = (props) => {
    const { data } = props ?? {};

    return confirmResetPassword(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type ConfirmResetPasswordMutationResult = NonNullable<Awaited<ReturnType<typeof confirmResetPassword>>>;
export type ConfirmResetPasswordMutationBody = BodyType<ConfirmPasswordResetRequest>;
export type ConfirmResetPasswordMutationError = ErrorType<HTTPValidationError>;

/**
 * @summary Confirm a password reset
 */
export const useConfirmResetPassword = <TError = ErrorType<HTTPValidationError>, TContext = unknown>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof confirmResetPassword>>,
      TError,
      { data: BodyType<ConfirmPasswordResetRequest> },
      TContext
    >;
    request?: SecondParameter<typeof createInstance>;
  },
  queryClient?: QueryClient,
): UseMutationResult<
  Awaited<ReturnType<typeof confirmResetPassword>>,
  TError,
  { data: BodyType<ConfirmPasswordResetRequest> },
  TContext
> => {
  return useMutation(getConfirmResetPasswordMutationOptions(options), queryClient);
};
